import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 46 Do it yourself","description":"学习 过去能力与一次成功，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 46 Do it yourself","description":"学习 过去能力与一次成功，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 过去能力与一次成功，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 45 The power of the press","link":"/life/english/new-concept/book-3/unit-03/lesson-045"},"next":{"text":"第三册：培养技能 · Lesson 47 Too high a price?","link":"/life/english/new-concept/book-3/unit-03/lesson-047"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 45 The power of the press","link":"/life/english/new-concept/book-3/unit-03/lesson-045"},"next":{"text":"第三册：培养技能 · Lesson 47 Too high a price?","link":"/life/english/new-concept/book-3/unit-03/lesson-047"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-046.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-046.md"}'),l={name:"life/english/new-concept/book-3/unit-03/lesson-046.md"};function i(s,e,r,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-46-do-it-yourself" tabindex="-1">第三册：培养技能 · Lesson 46 Do it yourself <a class="header-anchor" href="#第三册-培养技能-·-lesson-46-do-it-yourself" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 46 Do it yourself&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从自己维修与求助专业人员的选择练习能力、必要性和实际结果。自己能做不代表每次都该做，语言表达要清楚区分一般能力与某一次成功。学习 could、was able to 和 managed to 的差异，并用具体困难解释为何一次完成值得强调。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>tool</td><td>/tuːl/</td><td>n.</td><td>工具</td><td>the right tool</td></tr><tr><td>manual</td><td>/ˈmænjuəl/</td><td>n.</td><td>说明书</td><td>read the manual</td></tr><tr><td>assemble</td><td>/əˈsembl/</td><td>v.</td><td>组装</td><td>assemble a shelf</td></tr><tr><td>fault</td><td>/fɔːlt/</td><td>n.</td><td>故障</td><td>locate a fault</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>put together — 组装</li><li>call in — 请某专业人员前来</li></ul><h2 id="语法讲解-过去能力与一次成功" tabindex="-1">语法讲解：过去能力与一次成功 <a class="header-anchor" href="#语法讲解-过去能力与一次成功" aria-label="Permalink to &quot;语法讲解：过去能力与一次成功&quot;">​</a></h2><p>could 常表示过去的一般能力，也可用于感知、理解或特定条件下的可能性。描述过去某一次实际克服困难并成功完成，was able to 或 managed to 往往更明确；managed to 还暗含有难度。否定 couldn&#39;t 可以表示一次未能完成，因此不是简单地把 could 禁用于所有单次事件。能力、许可和可能性也可能共用 could，必须结合语境判断。维修叙述中应分别报告尝试与结果，tried to 不保证成功，managed to 则通常表示已实现。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>After several careful attempts, I managed to remove the damaged screw.</p></blockquote><p>经过几次小心尝试，我终于取出了损坏的螺丝。</p><p>managed to remove 表示实际成功，after 短语解释此前有困难和尝试。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I tried to fix it 不表示已经修好；若要确认成功，可写 I managed to fix it。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 tried to 和 managed to 的两组句子，在 managed 上强调成功；检查自己复述是否无意把尝试改成结果。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I could assemble simple shelves, but this kit had unclear labels. After sorting the parts by size, I managed to fit the frame together. I left the final wall mounting to an experienced installer.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句写一次低风险物品组装经历，说明困难和处理结果。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>一般能力、具体成功和能力边界各自清楚，不把部分成功说成全部完成。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句螺丝是否最终取出？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 是。</p><p><strong>解析：</strong> managed to 明确实际成功。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>描述童年一般能力：At ten, she ___ repair simple toys.（could/managed）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> could</p><p><strong>解析：</strong> 表达长期能力，managed 还需 to。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>couldn&#39;t open 是否可描述一次没打开？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 可以。</p><p><strong>解析：</strong> 否定 couldn&#39;t 可用于具体失败事件。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去能力与一次成功。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-045">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-047">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(l,[["render",i]]);export{p as __pageData,m as default};
